import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cx } from "../../lib/cx";
import { dateTime } from "../../lib/format";
import { SHEET, fitColumns, paginate } from "./layout";
import { SIGN_OFF, alignRight, cell, isNegative, tablesOf } from "./reportText";

// Reports as A4 landscape pages - on screen, printed, and (from the server,
// with the same layout.js) in the PDF:
//
//   Keiyian Farmers Cooperative Society Ltd
//   Nuru ya Jamii
//   Sales report - November 2026
//   Generated by <name> on 08 Nov 2026, 21:24 EAT
//
// then the Summary across the page and one ruled table per section, each
// column as wide as its content needs and the rest of the width shared
// evenly. The sign-off sits at the foot of the last page; every page has the
// footer and its page number. The tables are measured off screen first, then
// laid out page by page.

const PX = 96 / 25.4; // pixels to the millimetre
const PT = 96 / 72; // pixels to the point (the PDF works in points)
const SHEET_WIDTH = SHEET.width * PX;
const CONTENT_WIDTH = (SHEET.width - 2 * SHEET.margin) * PX;
const TYPE_SIZES = [8.5, 7.75, 7].map((size) => size * PT);
const PAD_X = 4.5 * PT;
const GAP = 14 * PT;
const FONT = 'Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const KEEP_ON_ONE_LINE = ["money", "number", "percent", "date"];
const EMPTY = "No records for this period.";

const words = (text) => String(text ?? "").split(/\s+/).filter(Boolean);

let canvas;
const widthOf = (text, bold, size) => {
  canvas ??= document.createElement("canvas").getContext("2d");
  canvas.font = `${bold ? 600 : 400} ${size}px ${FONT}`;
  return canvas.measureText(String(text ?? "")).width;
};

/** A table's text, type size and column widths for the page. */
const sizeTable = (section) => {
  const texts = section.rows.map((row) => section.columns.map((c) => String((section.pairs ? row[c.key] : cell(row[c.key], c.type)) ?? "")));
  const totals = section.totals
    ? section.columns.map((c, i) => (i === 0 ? section.totalLabel || "Total" : section.totals[c.key] == null ? "" : String(cell(section.totals[c.key], c.type))))
    : null;
  const pad = 2 * PAD_X + 3;
  const widthsAt = (size) => {
    if (section.pairs) {
      // Two equal halves; in each, the value takes what its longest figure needs.
      const value = Math.max(widthOf("Value", true, size), ...texts.flatMap((row) => [widthOf(row[1], false, size), widthOf(row[3], false, size)])) + pad;
      const half = CONTENT_WIDTH / 2;
      return [half - value, value, half - value, value];
    }
    return fitColumns(section.columns.map((column, i) => {
      const values = texts.map((row) => row[i]);
      const bold = totals ? [totals[i]] : [];
      const longest = Math.max(0, ...values.map((t) => widthOf(t, false, size)), ...bold.map((t) => widthOf(t, true, size)));
      const oneLine = KEEP_ON_ONE_LINE.includes(column.type) || alignRight(column);
      const longestWord = oneLine ? longest : Math.max(0, ...values.flatMap(words).map((w) => widthOf(w, false, size)), ...bold.flatMap(words).map((w) => widthOf(w, true, size)));
      const labelWord = Math.max(0, ...words(column.label).map((w) => widthOf(w, true, size)));
      return { min: Math.max(labelWord, longestWord) + pad, max: Math.max(widthOf(column.label, true, size), longest) + pad };
    }), CONTENT_WIDTH);
  };
  for (const size of TYPE_SIZES) {
    const widths = widthsAt(size);
    if (widths) return { section, texts, totals, size, widths };
  }
  // Wider than the page even in the smallest type: share the page in proportion and let long words break.
  const size = TYPE_SIZES[TYPE_SIZES.length - 1];
  const labels = section.columns.map((c) => widthOf(c.label, true, size) + pad);
  const all = labels.reduce((a, b) => a + b, 0);
  return { section, texts, totals, size, widths: labels.map((w) => (w / all) * CONTENT_WIDTH) };
};

/** Fonts must be in before anything is measured. */
const useFontsReady = () => {
  const [ready, setReady] = useState(() => !document.fonts || document.fonts.status === "loaded");
  useEffect(() => {
    if (!document.fonts) return undefined;
    let live = true;
    Promise.all(["400", "600", "700"].map((weight) => document.fonts.load(`${weight} 12px Inter`)))
      .catch(() => null)
      .then(() => document.fonts.ready)
      .finally(() => live && setReady(true));
    return () => { live = false; };
  }, []);
  return ready;
};

const SheetHeader = ({ heading, meta }) => (
  <header className="report-header report-sheet-header" data-m="header">
    <p className="report-org">{meta.organisation}</p>
    {meta.motto && <p className="report-motto">{meta.motto}</p>}
    <h2>{heading}</h2>
    <p className="report-generated">Generated by {meta.generatedBy} on {dateTime(meta.generatedAt)} EAT</p>
  </header>
);

const RunningHeader = ({ heading, meta }) => (
  <div className="report-running" data-m="running">
    <span className="report-running-org">{meta.organisation}</span>
    <span>{heading}</span>
  </div>
);

/** Sign-off lines, as on the cooperative's paper reports. */
const SignOff = () => (
  <div className="report-signoff" data-m="signoff">
    {SIGN_OFF.map((role) => (
      <div key={role} className="report-signoff-row">
        <span>{role}:</span>
        <span className="report-signoff-line" />
        <span className="report-signoff-label">Signature:</span>
        <span className="report-signoff-line" />
        <span className="report-signoff-label">Date:</span>
        <span className="report-signoff-line" />
      </div>
    ))}
  </div>
);

/** One table, or the part of it on one page (rows from <= i < to). Measuring draws it whole, with both titles. */
const SheetTable = ({ table, block, measuring = false }) => {
  const { section, texts, totals, size, widths } = table;
  const rows = measuring ? texts : texts.slice(block.from, block.to);
  const first = block?.from ?? 0;
  const pairEdge = (i) => section.pairs && i === 1 && "is-pair-edge";
  return (
    <section className={cx("report-table", section.pairs && "report-summary")} data-m={measuring ? "table" : undefined}>
      {(measuring || !block.continued) && <h3 className="report-table-title" data-m="title">{section.title}</h3>}
      {(measuring || block.continued) && <p className="report-table-title is-continued" data-m="continued">{section.title} (continued)</p>}
      <table style={{ fontSize: `${size}px` }}>
        <colgroup>{widths.map((w, i) => <col key={i} style={{ width: `${w}px` }} />)}</colgroup>
        <thead>
          <tr>{section.columns.map((c, i) => <th key={c.key} scope="col" className={cx(alignRight(c) && "is-right", pairEdge(i))}>{c.label}</th>)}</tr>
        </thead>
        <tbody>
          {texts.length === 0 ? (
            <tr><td colSpan={section.columns.length} className="is-empty">{section.emptyText || EMPTY}</td></tr>
          ) : rows.map((row, r) => (
            <tr key={first + r}>
              {row.map((text, i) => {
                const column = section.columns[i];
                return (
                  <td
                    key={column.key}
                    className={cx(
                      alignRight(column) && "is-right",
                      KEEP_ON_ONE_LINE.includes(column.type) && "is-nowrap",
                      isNegative(text, column) && "is-negative",
                      pairEdge(i),
                    )}
                  >
                    {text}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
        {totals && (measuring || block.foot) && (
          <tfoot>
            <tr>{totals.map((text, i) => <td key={section.columns[i].key} className={cx(alignRight(section.columns[i]) && "is-right", isNegative(text, section.columns[i]) && "is-negative")}>{text}</td>)}</tr>
          </tfoot>
        )}
      </table>
    </section>
  );
};

/** Heights of everything on the measuring sheets, for the page planner. */
const measure = (node, layout) => {
  const height = (el) => el.getBoundingClientRect().height;
  const page = height(node.querySelector("[data-m=page]"));
  const reports = layout.map((_, r) => {
    const box = node.querySelector(`[data-report="${r}"]`);
    return {
      header: height(box.querySelector("[data-m=header]")),
      runningHeader: height(box.querySelector("[data-m=running]")),
      signOff: height(box.querySelector("[data-m=signoff]")),
      tables: [...box.querySelectorAll("[data-m=table]")].map((section) => {
        const table = section.querySelector("table");
        const body = table.tBodies[0];
        return {
          title: height(section.querySelector("[data-m=title]")),
          continuedTitle: height(section.querySelector("[data-m=continued]")),
          head: body.getBoundingClientRect().top - table.getBoundingClientRect().top,
          rows: [...body.rows].map(height),
          foot: table.tFoot ? height(table.tFoot) : 0,
        };
      }),
    };
  });
  // A pixel or two in hand for rounding, so nothing runs into the footer.
  return paginate(reports, { page: page - 3, gap: GAP });
};

const Footer = ({ meta, number, count }) => (
  <footer className="report-sheet-foot">
    <span className="report-sheet-note">This is a system generated report. Generated {dateTime(meta.generatedAt)} EAT.</span>
    <span>Page {number} of {count}</span>
  </footer>
);

/** The pages, each report's in its own .report-document. */
const Pages = ({ plan }) => {
  const { layout, meta, pages } = plan;
  return layout.map(({ report, tables }, r) => (
    <article key={`${report.department}-${report.part || ""}-${r}`} className="report-document" aria-label={report.heading}>
      {pages.map((page, index) => page.report === r && (
        <div key={index} className="report-sheet">
          <div className="report-sheet-body">
            {page.first ? <SheetHeader heading={report.heading} meta={meta} /> : <RunningHeader heading={report.heading} meta={meta} />}
            {page.blocks.map((block) => (block.type === "signoff"
              ? <SignOff key="signoff" />
              : <SheetTable key={`${block.table}-${block.from}`} table={tables[block.table]} block={block} />))}
          </div>
          <Footer meta={meta} number={index + 1} count={pages.length} />
        </div>
      ))}
    </article>
  ));
};

/** Scales the pages down to fit a narrower screen (a phone shows a whole page; pinch to read). */
const FitWidth = ({ children }) => {
  const [zoom, setZoom] = useState(1);
  const observer = useRef(null);
  const ref = useCallback((node) => {
    observer.current?.disconnect();
    if (!node) return;
    observer.current = new ResizeObserver(() => setZoom(Math.min(1, node.clientWidth / (SHEET_WIDTH + 2))));
    observer.current.observe(node);
  }, []);
  return (
    <div ref={ref} className="w-full">
      <div className="report-sheets" style={{ zoom }}>{children}</div>
    </div>
  );
};

/**
 * reports: [{ heading, summary, sections }] and meta: { organisation, motto,
 * generatedBy, generatedAt } from the report API. Print prints these pages
 * alone (see .print-root in index.css).
 */
export const ReportSheets = ({ reports, meta }) => {
  const fontsReady = useFontsReady();
  const layout = useMemo(
    () => (fontsReady ? reports.map((report) => ({ report, tables: tablesOf(report).map(sizeTable) })) : null),
    [reports, fontsReady],
  );
  const [plan, setPlan] = useState(null);
  const measured = useCallback((node) => {
    if (node && layout) setPlan({ layout, meta, pages: measure(node, layout) });
  }, [layout, meta]);

  const measuring = layout && layout.length > 0 && plan?.layout !== layout;
  if (!reports.length) return null;
  return (
    <>
      {measuring && createPortal(
        <div ref={measured} className="report-measure" aria-hidden="true">
          <div className="report-sheet"><div className="report-sheet-body" data-m="page" /><Footer meta={meta} number={1} count={1} /></div>
          {layout.map(({ report, tables }, r) => (
            <div key={r} className="report-sheet is-measuring" data-report={r}>
              <div className="report-sheet-body">
                <SheetHeader heading={report.heading} meta={meta} />
                <RunningHeader heading={report.heading} meta={meta} />
                {tables.map((table, t) => <SheetTable key={t} table={table} measuring />)}
                <SignOff />
              </div>
            </div>
          ))}
        </div>,
        document.body,
      )}
      {plan && plan.layout.length > 0 && (
        <>
          <FitWidth><Pages plan={plan} /></FitWidth>
          {createPortal(<div className="print-root"><div className="report-sheets"><Pages plan={plan} /></div></div>, document.body)}
        </>
      )}
    </>
  );
};
